import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.yMGLHqpH.js";const g=JSON.parse('{"title":"Gentoo / Calculate","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/gentoo.md","filePath":"zh-CN/guide/gentoo.md"}'),o={name:"zh-CN/guide/gentoo.md"};function n(r,e,h,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="gentoo-calculate" tabindex="-1">Gentoo / Calculate <a class="header-anchor" href="#gentoo-calculate" aria-label="标题链接： &quot;Gentoo / Calculate&quot;">​</a></h1><p>Gentoo 用户可通过 <a href="https://github.com/gentoo-zh/overlay/tree/master/net-proxy/dae" target="_blank" rel="noreferrer">gentoo-zh overlay</a> 安装 <code>net-proxy/dae</code>。该软件包由 Gentoo 社区维护，使用 Portage 管理。本网站的 APT/RPM 版本表对应另一个软件源。</p><p>以下命令以 root 身份执行，测试关键字示例适用于 amd64 系统。</p><h2 id="_1-添加并同步-overlay" tabindex="-1">1. 添加并同步 overlay <a class="header-anchor" href="#_1-添加并同步-overlay" aria-label="标题链接： &quot;1. 添加并同步 overlay&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-eselect/eselect-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-vcs/git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eselect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/gentoo-zh/overlay.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emaint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span></span></code></pre></div><p>如果已经配置 gentoo-zh，只需执行同步命令。镜像选择和手动配置方法见 <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay 文档</a>。</p><h2 id="_2-接受测试关键字" tabindex="-1">2. 接受测试关键字 <a class="header-anchor" href="#_2-接受测试关键字" aria-label="标题链接： &quot;2. 接受测试关键字&quot;">​</a></h2><p>使用稳定关键字的 amd64 系统需要在 <code>package.accept_keywords</code> 中添加以下配置。如果 <code>/etc/portage/package.accept_keywords</code> 是目录，可写入其中的 <code>/etc/portage/package.accept_keywords/dae</code> 文件；如果它是文件，则直接在该文件中添加。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net-proxy/dae::gentoo-zh ~amd64</span></span></code></pre></div><p>已全局接受 <code>~amd64</code> 的系统可跳过此步骤。其他架构需先检查所选 ebuild 的 <code>KEYWORDS</code>，再选择对应的关键字。</p><h2 id="_3-安装-dae" tabindex="-1">3. 安装 dae <a class="header-anchor" href="#_3-安装-dae" aria-label="标题链接： &quot;3. 安装 dae&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> net-proxy/dae::gentoo-zh</span></span></code></pre></div><p>检查 Portage 给出的内核配置提示。ebuild 会安装 OpenRC、systemd 服务文件，并将配置示例放在 <code>/usr/share/dae/config.dae.example</code>。启动服务前应先完成 dae 配置，详见 <a href="https://github.com/daeuniverse/dae#readme" target="_blank" rel="noreferrer">dae 文档</a>。</p><h2 id="可选-镜像与二进制包" tabindex="-1">可选：镜像与二进制包 <a class="header-anchor" href="#可选-镜像与二进制包" aria-label="标题链接： &quot;可选：镜像与二进制包&quot;">​</a></h2><p>Distfiles 镜像、binhost 频道和签名验证的配置方法见 <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay 文档</a>。可用的二进制包以<a href="https://distfiles.gentoozh.org/packages" target="_blank" rel="noreferrer">软件包列表</a>为准；没有合适的二进制包时，Portage 可以从源代码编译。</p>`,15)])])}const k=a(o,[["render",n]]);export{g as __pageData,k as default};
